        "create_assign_prioritize_monitor_projects_text": "आसानी से प्रोजेक्ट्स बनाएं, सौंपें, प्राथमिकता निर्धारित करें और निगरानी रखें। टीम के सदस्य अपने कार्यों को स्पष्ट रूप से देख सकते हैं, व्यवस्थित रह सकते हैं और कार्यक्षमता और उत्पादकता बढ़ा सकते हैं। नया प्रोजेक्ट शुरू करने के लिए यहां क्लिक करें।",
        "track_users_time_sheet_reports_text": "विभिन्न टाइम शीट रिपोर्ट्स जैसे यूजर टाइम शीट, प्रोजेक्ट टाइम शीट, वर्कलोड टाइम शीट, और ट्रैकर टाइमशीट के माध्यम से यूजर्स का समय प्रभावी ढंग से ट्रैक करें। टाइम शीट रिपोर्ट्स देखने के लिए यहां क्लिक करें।",
        "user_time_sheet_description_text": "यूजर टाइम शीट आपको प्रत्येक उपयोगकर्ता द्वारा लॉग की गई घंटों को आपके यूजर रोल के अनुसार मॉनिटर करने की सुविधा देती है।",
        "project_time_sheet_description_text": "प्रोजेक्ट टाइम शीट में आपके यूजर रोल के आधार पर प्रत्येक प्रोजेक्ट के लिए लॉग की गई घंटों का ट्रैक रखें।",
        "workload_time_sheet_description_text": "यूजर टाइम शीट के समान, वर्कलोड टाइम शीट में यूजर के कार्यभार, कुल घंटे, और अनुमानित घंटों की जानकारी भी शामिल होती है।",
        "tracker_sheet_description_text": "ट्रैकर शीट समय ट्रैकर के माध्यम से लॉग किए गए समय को, साथ ही स्क्रीनशॉट्स और कुल ट्रैक किए गए समय को दिखाती है।",
        "view_companies_switch_text": "सभी कंपनियां देखें जिनसे आप जुड़े हुए हैं और उन्हें एक को चुनकर आसानी से स्विच करें।",
        "engage_team_real_time_text": "त्वरित निर्णय लेने के लिए टीम के सदस्यों के साथ वास्तविक समय में जुड़ें। चैनल बनाएं और अटैचमेंट्स, वॉयस मैसेजेस और टेक्स्ट के माध्यम से जानकारी साझा करें।",
        "real_time_notifications_text": "प्रोजेक्ट और कार्य गतिविधियों के बारे में वास्तविक समय में सूचनाओं के साथ अद्यतन रहें, जिसमें कार्य असाइनमेंट, स्थिति परिवर्तन, टिप्पणियां, और डेडलाइन्स शामिल हैं।",
